-- p4_32 — refresh the specimen at /report/example/ with the 2026-07-28 report,
-- and reword the provenance so every published claim is true of THIS report.
--
-- Owner decision 2026-07-29 (session "idea.uk vm 9"): reword + refresh. The old
-- specimen (ord_1785090638951163875, bought 26 July) predated the copy/format
-- fixes and admitted two hand-made typographical corrections. The new source is
-- ord_1785274337709242206 (28 July): produced by the current binary, both fixes
-- exercised and proven (NOTES §X.30), zero corrections needed.
--
-- PROVENANCE — what changed and why it stays honest:
--   * "bought and delivered ... for £29" is GONE: this run was declined at the
--     draft, so the page now says "produced on 28 July 2026 by exactly the
--     process that writes every £29 report".
--   * The idea is declared as OUR OWN worked example (it was authored by us to
--     exercise the scoring path; the owner's ban on using Will's idea stands).
--   * The two-typo admission is DROPPED because this report needed none.
--   * The heading "The report, exactly as it was sent" becomes "The report, in
--     full" — this one was never sent.
--   * Verbatim-ness was proven mechanically before this file was written: the
--     tag-stripped word stream of the HTML equals the stored text report's,
--     differing only in heading colons, badge brackets and URLs-into-hrefs.
--
-- Same shape as p4_27: full content_data replacement (heading + content in one
-- write), required-field guard, then a page_rerender with
-- reason='section_data_resolved' (assemble-only cannot see content_data edits).
\set ON_ERROR_STOP on

BEGIN;

UPDATE page_components pc
SET content_data = $p432${"heading": "The report, in full", "content": "<p class=\"note\"><strong>This is a real report, reproduced in full.</strong> It was produced on 28 July 2026 by exactly the process that writes every \u00a329 report. Nothing has been added, removed or reworded.</p>\n<p class=\"note\">The idea it assesses is a worked example we submitted ourselves, not a customer&#x27;s idea. We would not publish a customer&#x27;s report without their agreement.</p>\n<hr>\n<p>This report is from idea.uk. Here is the idea you sent us: We run pre-tenancy and end-of-tenancy inventory inspections for residential letting agents across the UK, and over twelve years we have built up time-stamped photographic condition records on roughly 40,000 rental properties, each linked to the deposit adjudicator&#x27;s decision where the tenancy ended in a dispute.</p>\n<p>It comes in two parts. First we assess the idea you sent: the problem it addresses, the evidence that people have it, who else is already out there, where it is defensible, where it is exposed, and a specific next step. Then we look for further ideas around it \u2014 checking each against what already exists and whether people would actually pay \u2014 and set out the ones worth pursuing, along with the ones we set aside and why.</p>\n<p>We use AI to research and draft this report, with live web searches for the checking, and a person reads it before it is sent. Where a finding rests on something we read, the source is listed underneath so you can check it yourself.</p>\n<h2>Your idea, assessed</h2>\n<p class=\"reading\"><em>(You did not submit a single product idea. You described a business and an unusually good asset: twelve years of dated inspection photos on about 40,000 rental homes, with roughly 6,000 of those linked to how the deposit adjudicator actually ruled. So we have assessed the proposition your business already implies, which is: we are the inspection firm whose reports hold up when a deposit claim is challenged, because we can see how thousands of real disputes were decided.)</em></p>\n<h3>The problem, and the evidence people have it</h3>\n<p>The problem is that letting agents and landlords lose money on deposit claims because their evidence does not stand up, and they have no way of knowing that before they submit. This is real and documented, not guesswork. The Tenancy Deposit Scheme&#x27;s own figures for the year to March 2025 (reported by the National Residential Landlords Association) show about 4.7 million deposits protected in England and Wales, an average deposit of \u00a31,175, and roughly 1% of deposits, about 46,950 cases, going to formal adjudication. The scheme&#x27;s published analysis says cleaning is the single biggest cause and appears in over half of its dispute cases, with damage to fixtures and fittings second. Its chief executive has said publicly that this points to the importance of good check-in and check-out reports. There are also named, published examples of claims failing on evidence. Property Industry Eye reported an adjudication where the agent&#x27;s check-in report was described as vague and did not contain enough to help the landlord, and noted that adjudicators tend to give less weight to reports not written by an independent inventory clerk. The Deposit Protection Service published a case, covered by Estate Agent Today, where conflicting check-in paperwork and no supporting evidence left the adjudicator no choice but to decide for the tenant. One honest caveat, and it matters: 99% of tenancies end with no dispute at all. For an agent managing 1,000 tenancies that is a handful of contested cases a month, not a daily fire. A problem that is real but occasional puts a low ceiling on what people will pay to fix it.</p>\n<h3>Signs of real demand</h3>\n<p>The strongest demand evidence in this whole submission is your own: 300 agency clients on rolling annual contracts, paying repeatedly for inspections. That is money already moving, which most ideas cannot show. Second, software firms are already selling artificial intelligence report writing to exactly your audience, which means they believe agents will pay for it. Peach Software advertises that its tool turns photos and notes into report text and claims reports up to 70% faster. Inspecto sells a video walkthrough that becomes a report. The Property AI advertises detection of items, condition and damage from photos and describes its output as ready for use as deposit dispute evidence. InventoryBase, a long-standing name here, is now advertising artificial intelligence features too. On the trade side, the Association of Independent Inventory Clerks says it has over 1,350 members, so this is a real occupation with real spend around it. Now the honest part. We found no product anywhere that people pay for which predicts how an adjudicator will rule, or scores a claim&#x27;s chance of success. No pricing page for it, no case studies, no agents complaining that it is missing. So the specific thing your archive makes possible is unproven demand, not a known market waiting to be served. You would be testing whether anyone wants it, not filling a queue.</p>\n<h3>Who else is addressing it, and how</h3>\n<p>Three groups. First, and most important, the deposit schemes themselves. The Tenancy Deposit Scheme already puts a free Disputes Chatbot on its own website, described as a way to find out how successful your claim would be and what you need to do to present it properly. It also publishes an Adjudication Digest that takes a real decision and explains the reasoning, offers free real-life case studies, and sells adjudication workshops through its training arm. They hold every decision they have ever made, tens of thousands a year, plus the reasons. Second, the software firms: InventoryBase, Inventory Hive, Peach Software, Inspecto and The Property AI. They are all adding photo-to-report writing and some claim damage detection. InventoryBase also runs a network for farming inspections out to freelance clerks, which is close to your own model. Third, other inspection firms competing on speed and accreditation, such as InventoryFlex in London, which advertises accredited clerks and next-day report delivery.</p>\n<h3>What people would use instead today</h3>\n<p>An agent who wants to know if a claim will stand up does four things today, all cheap or free. One, they use the deposit scheme&#x27;s free material: the chatbot, the digest of real decisions, and the guide on presenting a case. Two, they ask their most experienced property manager, who has seen a hundred check-outs and has a gut feel. Three, they rely on the inventory software they already pay for, which sells its templates as dispute-ready. Four, they use a free chatbot on their phone. An agent can drop three photos into a free tool and get a tidy paragraph about a stained carpet in ten seconds. That last point is the one to sit with: the writing-up part of this is already free and good enough. And the biggest substitute of all is doing nothing and splitting the difference with the tenant, which is what happens in most cases before anyone reaches adjudication.</p>\n<h3>Where it is defensible</h3>\n<p>Four things here are genuinely hard for someone else to copy. First, the 6,000 cases where you hold both the condition of the property and the ruling that followed. Photos on their own are not rare, everybody has photos. Photos with the answer attached are rare outside the deposit schemes. Second, your distribution: 300 paying clients and 90 inspectors. A software firm with a clever feature still has to win those clients one phone call at a time, and you already have them on contract. Third, you own your own scheduling and reporting software, so you can add something new without asking another company for permission or paying them a cut. Fourth, twelve years of one consistent method means the same flat can be compared across three different tenancies. That answers a question nobody else can answer: was that mark already there when the last tenant moved in. Worth noting, the most defensible version of this needs no machine learning at all. It is a second opinion service: a person with access to your archive telling an agent whether a claim is worth making.</p>\n<h3>Where it is exposed</h3>\n<p>Six real weaknesses. One, the deposit schemes are one feature away from owning this. The Tenancy Deposit Scheme already has a claim-strength chatbot on its site. If it deepens that using its full decision history, nothing you hold can match it, and it has no reason to share the data with you. Two, your dataset is thinner than 6,000 sounds. Split it by issue type, then property type, then region, then year, and each pocket becomes small. Worse, an adjudicator&#x27;s decision is usually one money figure covering a whole case, not a verdict on each item or each photo. Connecting a specific photo to a specific outcome is slow manual work that somebody has to pay for before anything clever can happen. Three, permission. Those photos were taken for your clients, inside people&#x27;s homes, showing tenants&#x27; belongings. Your client contracts may not allow you to re-use the material for a new product, and the images contain information about identifiable people. That is a contract and privacy question for a solicitor, and it needs answering before you spend anything. It is not a licensing problem, so it does not breach your stated red line, but it is a genuine blocker if the answer is no. Four, you have no machine learning capability, so you would buy it in. Bought capability is available to your competitors on the same terms. The clever model is never the moat, the archive is. Five, the rare-event problem. It is hard to charge a monthly fee for something an agent uses twice a month, so this probably has to be priced per case, which caps the revenue. Six, the ground is moving. The Renters&#x27; Rights Act 2025 brings a new landlord ombudsman and a national database of rented properties, with a government roadmap published in November 2025 pointing to late 2026 and beyond. Past decisions may become a weaker guide to future ones. And if you tell an agent a claim will win and it loses, expect to be blamed, so any such service must be worded as an opinion, never a promise.</p>\n<h3>A considered next step</h3>\n<p>Sell the service by hand, for money, before you build anything. This week, pick the 20 agency clients who send you the most check-outs. Offer them one thing: before they submit a deposit claim, they send you the check-in and check-out reports, and within two working days a senior member of your team compares them against similar decided cases in your archive and sends back a single page. That page says how strong the claim looks, which items an adjudicator is likely to cut, what extra evidence to add before submitting, and a realistic figure to claim. Charge a fixed fee of \u00a345 to \u00a360 per claim and invoice it. No software, no artificial intelligence, no development spend, just one experienced person and your own files. Take payment up front, discounted for the first ten if you must, but never free, because a free trial tells you nothing about willingness to pay. Set your decision rule now, in writing: if fewer than 6 of the 20 clients buy, and fewer than 25 claims come in over six weeks, the claim-prediction idea is not the one to build and you should stop. If they do buy, you will have written 25 of these pages by hand, and you will know precisely what a tool would need to do, which is the only sound basis for spending money on one.</p>\n<h3>Check it yourself</h3>\n<ul class=\"sources\">\n<li><a href=\"https://www.nrla.org.uk/news/what-2025-taught-us-about-deposit-disputes\" rel=\"nofollow noopener\" target=\"_blank\">What 2025 taught us about deposit disputes: lessons from the Tenancy Deposit Scheme adjudication team (National Residential Landlords Association)</a></li>\n<li><a href=\"https://www.tenancydepositscheme.com/statistical-briefing-from-tds-group/\" rel=\"nofollow noopener\" target=\"_blank\">Statistical Briefing from TDS Group highlights deposit increases and dispute trends (Tenancy Deposit Scheme)</a></li>\n<li><a href=\"https://www.tdsgroup.uk/resolution-service\" rel=\"nofollow noopener\" target=\"_blank\">Resolution Services, including the free Disputes Chatbot and adjudication case studies (TDS Group)</a></li>\n<li><a href=\"https://propertyindustryeye.com/deposit-dispute-agents-vague-check-in-report-lacked-enough-evidence-to-help-landlord/\" rel=\"nofollow noopener\" target=\"_blank\">Deposit dispute: agent&#x27;s vague check-in report lacked enough evidence to help landlord (Property Industry Eye)</a></li>\n<li><a href=\"https://www.estateagenttoday.co.uk/features/2019/07/dps-adjudication-case-study-conflicting-paperwork-and-a-burden-of-proof/\" rel=\"nofollow noopener\" target=\"_blank\">Deposit Protection Service adjudication case study: conflicting paperwork and a burden of proof (Estate Agent Today)</a></li>\n<li><a href=\"https://thepropertyai.co.uk/\" rel=\"nofollow noopener\" target=\"_blank\">The Property AI: artificial intelligence property inventory software for UK letting agents and inventory clerks</a></li>\n<li><a href=\"https://thepropertyai.co.uk/property-news/inventory-hive-alternatives-in-2026-7-top-uk-property-inventory-tools\" rel=\"nofollow noopener\" target=\"_blank\">Inventory Hive alternatives in 2026: seven UK property inventory tools compared, including InventoryBase and Peach</a></li>\n<li><a href=\"https://www.hoganlovells.com/en/publications/renters-rights-act-implementation-roadmap-now-published\" rel=\"nofollow noopener\" target=\"_blank\">Renters&#x27; Rights Act: implementation roadmap now published (Hogan Lovells)</a></li>\n</ul>\n<h2>Who it&#x27;s for</h2>\n<p>UK residential letting agents and build-to-rent operators managing roughly 200 to 5,000 tenancies each \u2014 the same firms already on your books \u2014 with the specific buyer being the person who signs off deposit deductions at the end of a tenancy.</p>\n<h2>Why they&#x27;d pay</h2>\n<p>They already pay you per inspection, so there is a live budget and no new purchase process; a losing deposit dispute costs them the deduction plus staff hours plus an angry landlord, so a tool that tells them, before they claim, what an adjudicator is likely to allow has clear money attached. Realistically they would pay a modest amount per tenancy end or a monthly fee per branch, not a large licence fee, because they are cost-conscious and buy in small steps.</p>\n<h2>Further ideas worth pursuing (best first)</h2>\n<h3>1) Claim letter writer that quotes the evidence we hold <span class=\"badge\">worth testing now</span></h3>\n<p>It writes from the actual file for that tenancy, including photo references, instead of producing a blank template the agent must fill in by hand</p>\n<p><strong>What it&#x27;s built on:</strong> Our own inspection reports and photo files for that exact property, check-in and check-out, using an AI that writes the finished claim submission, item by item, pointing to the specific photos and report lines that back each item.</p>\n<p><strong>What we found:</strong> I checked what agents actually complain about and what today&#x27;s inventory apps already do. Published research on agents&#x27; views found the paperwork and the burden of proving the claim is their main gripe, and current apps do produce side-by-side before-and-after reports but still leave the agent to write the claim itself. So the gap is real, but this is a busy corner of the market and the only thing protecting it is that you hold the file.</p>\n<p><strong>How it scored:</strong> (each out of 5) hard to copy 3, people will pay 4, easy to build 4, reusable elsewhere 3, built to last 3 (18 out of 25 overall).</p>\n<p><strong>Risk to you:</strong> 4/5 (low \u2014 a mistake would be minor, and a refund would put it right)</p>\n<p><strong>A cheap first test:</strong> Write ten real claim letters this way for existing clients this month and ask if they would pay extra for it going forward, since building it needs little more than assembling data you already hold.</p>\n<h4>Check it yourself</h4>\n<ul class=\"sources\">\n<li><a href=\"https://www.emerald.com/insight/content/doi/10.1108/ijlbe-09-2014-0026/full/html\" rel=\"nofollow noopener\" target=\"_blank\">Adjudication in tenancy deposit scheme disputes: agents&#x27; perspectives</a></li>\n<li><a href=\"https://www.inventoryhive.co.uk/\" rel=\"nofollow noopener\" target=\"_blank\">Inventory Hive | Property Inventory Software</a></li>\n<li><a href=\"https://thepropertyai.co.uk/\" rel=\"nofollow noopener\" target=\"_blank\">AI Property Inventory Software for UK Letting Agents &amp; Inventory Clerks</a></li>\n</ul>\n<h3>2) Second opinion on a claim the tenant is fighting <span class=\"badge\">worth testing now</span></h3>\n<p>It is advising from recorded outcomes of similar pushbacks, not general reasoning</p>\n<p><strong>What it&#x27;s built on:</strong> Decisions where tenants pushed back and what happened next, using an AI that reads the tenant&#x27;s objection and the file, then advises settle, reduce or hold firm, with a rough likely outcome.</p>\n<p><strong>What we found:</strong> I checked whether there is a real settle-or-hold moment and who already helps with it. Roughly a quarter of deposit disputes are now settled by agreement before any formal decision, and the schemes offer free talks between the parties but no view on what you would probably be awarded if you pushed on. That missing number is exactly what your past pushback outcomes can supply.</p>\n<p><strong>How it scored:</strong> (each out of 5) hard to copy 5, people will pay 4, easy to build 3, reusable elsewhere 2, built to last 4 (18 out of 25 overall).</p>\n<p><strong>Risk to you:</strong> 3/5 (moderate \u2014 show your sources; insurance for handling personal data is recommended)</p>\n<p><strong>A cheap first test:</strong> Offer a few agents a free second opinion the next time a tenant pushes back on a claim, telling them settle, reduce, or hold firm with a rough likely outcome, and ask if they would pay for this going forward.</p>\n<h4>Check it yourself</h4>\n<ul class=\"sources\">\n<li><a href=\"https://www.propertywire.com/news/uk/sharp-rise-in-tenancy-deposit-disputes-being-resolved-before-adjudication/\" rel=\"nofollow noopener\" target=\"_blank\">Sharp rise in tenancy deposit disputes being resolved before adjudication</a></li>\n<li><a href=\"https://www.tdsgroup.uk/resolution-service\" rel=\"nofollow noopener\" target=\"_blank\">Resolution Services | TDS Group</a></li>\n<li><a href=\"https://ww3.rics.org/uk/en/journals/property-journal/resolving-tenancy-deposit-disputes.html\" rel=\"nofollow noopener\" target=\"_blank\">Resolving tenancy deposit disputes | RICS Property Journal</a></li>\n</ul>\n<h3>3) Will this deduction stick? A before-you-claim check <span class=\"badge\">worth testing now</span></h3>\n<p>A free chatbot has never seen a single real adjudicator decision with the matching photos, so it can only guess at the rules of thumb we can actually measure</p>\n<p><strong>What it&#x27;s built on:</strong> Our 6,000 finished deposit disputes, where we have the photos from check-in and check-out plus the adjudicator&#x27;s written decision and how much they actually allowed, using an AI that reads the photos and the draft claim, finds the closest past cases, and gives a plain answer: likely allowed in full, likely reduced, or likely refused, with the past decisions it is copying from.</p>\n<p><strong>What we found:</strong> I checked how many deposit claims actually reach a formal decision and whether those decisions are public. About one in a hundred protected deposits goes to a formal decision, roughly 47,000 cases a year, and the written decisions stay private between the two parties, with only a short anonymised summary of one case published each month. The process is free but binding with no appeal on the facts, so the thing a buyer is weighing is the money at stake, not a fee.</p>\n<p><strong>How it scored:</strong> (each out of 5) hard to copy 5, people will pay 4, easy to build 2, reusable elsewhere 2, built to last 4 (17 out of 25 overall).</p>\n<p><strong>Risk to you:</strong> 3/5 (moderate \u2014 show your sources; insurance for handling personal data is recommended)</p>\n<p><strong>A cheap first test:</strong> Put up a simple one-page offer to letting agents: send us your draft deduction and photos, we will tell you if it is likely to be allowed in full, reduced, or refused, for a small fee, and see if anyone pays before building anything.</p>\n<h4>Check it yourself</h4>\n<ul class=\"sources\">\n<li><a href=\"https://www.nrla.org.uk/news/what-2025-taught-us-about-deposit-disputes\" rel=\"nofollow noopener\" target=\"_blank\">What 2025 taught us about deposit disputes: Lessons from the Tenancy Deposit Scheme adjudication team</a></li>\n<li><a href=\"https://www.nrla.org.uk/news/the-adjudication-digest\" rel=\"nofollow noopener\" target=\"_blank\">TDS: The Adjudication Digest</a></li>\n<li><a href=\"https://www.augustapp.com/dictionary/adjudication\" rel=\"nofollow noopener\" target=\"_blank\">Adjudication: deposit disputes and how it works</a></li>\n</ul>\n<h3>4) Missing-evidence warning before check-out day <span class=\"badge\">worth testing now</span></h3>\n<p>It knows which gaps actually lost money in our own cases, and it can read our specific file for this property</p>\n<p><strong>What it&#x27;s built on:</strong> The pattern of which weak spots caused past claims to fail, for example no check-in photo of the oven interior or no meter reading, using an AI that reads the check-in file and lists what the inspector must photograph at check-out to keep a claim winnable.</p>\n<p><strong>What we found:</strong> I checked whether advice on what evidence you need is already free, and whether the failure patterns are known. General checklists are published by the schemes, and it is widely written up that claims collapse without a signed check-in record and photos, so the broad lesson is not private. What nothing public can do is read this particular property&#x27;s check-in file and name what is missing before the tenant hands the keys back, which is where your value sits.</p>\n<p><strong>How it scored:</strong> (each out of 5) hard to copy 3, people will pay 3, easy to build 3, reusable elsewhere 3, built to last 3 (15 out of 25 overall).</p>\n<p><strong>Risk to you:</strong> 4/5 (low \u2014 a mistake would be minor, and a refund would put it right)</p>\n<p><strong>A cheap first test:</strong> Offer a small group of agents a free one-month trial of an emailed pre-check-out warning list and ask afterwards whether they would pay to keep receiving it.</p>\n<h4>Check it yourself</h4>\n<ul class=\"sources\">\n<li><a href=\"https://www.propertypassport.uk/guides/tds-tenancy-deposit-scheme-dispute-guide\" rel=\"nofollow noopener\" target=\"_blank\">TDS (Tenancy Deposit Scheme): How to Raise a Dispute Step by Step</a></li>\n<li><a href=\"https://www.mydeposits.co.uk/content-hub/deposit-dispute-process/\" rel=\"nofollow noopener\" target=\"_blank\">Tenancy Deposit Disputes Explained: Process &amp; Evidence</a></li>\n<li><a href=\"https://www.emerald.com/insight/content/doi/10.1108/ijlbe-09-2014-0026/full/html\" rel=\"nofollow noopener\" target=\"_blank\">Adjudication in tenancy deposit scheme disputes: agents&#x27; perspectives</a></li>\n</ul>\n<h3>5) Cleaning versus redecorating: which claim to make <span class=\"badge\">worth testing now</span></h3>\n<p>The distinction is a quirk of how adjudicators decide, learned from our decision texts, not from anything published</p>\n<p><strong>What it&#x27;s built on:</strong> Past decisions where a claim failed only because it was described as the wrong thing, using an AI that reads the photos and advises which category to claim under and what the wording should say.</p>\n<p><strong>What we found:</strong> I checked how big this issue is and whether the distinction is really unpublished. Cleaning has been the single most common reason for deposit claims for five years running and redecoration is a large slice too, so the volume is there. But the rule that cleaning is judged separately from normal ageing is already written up publicly, so the only private part is the wording that actually held up in your own decided cases.</p>\n<p><strong>How it scored:</strong> (each out of 5) hard to copy 3, people will pay 4, easy to build 3, reusable elsewhere 2, built to last 3 (15 out of 25 overall).</p>\n<p><strong>Risk to you:</strong> 3/5 (moderate \u2014 show your sources; insurance for handling personal data is recommended)</p>\n<p><strong>A cheap first test:</strong> Offer agents a free check on their next ten cleaning or redecoration claims, telling them which category to use and why, and see if they ask to keep paying for it.</p>\n<h4>Check it yourself</h4>\n<ul class=\"sources\">\n<li><a href=\"https://propertyindustryeye.com/main-cause-of-tenancy-deposit-disputes-revealed/\" rel=\"nofollow noopener\" target=\"_blank\">Main cause of tenancy deposit disputes revealed</a></li>\n<li><a href=\"https://www.oakwood-inventories.com/post/betterment-and-apportionment-in-tenancy-deposits\" rel=\"nofollow noopener\" target=\"_blank\">Betterment and Apportionment in Tenancy Deposits</a></li>\n<li><a href=\"https://www.property118.com/deposit-disputes-remain-rare-despite-rising-rents-tds/\" rel=\"nofollow noopener\" target=\"_blank\">Deposit disputes remain rare despite rising rents - TDS</a></li>\n</ul>\n<h3>6) Fair wear and tear line-drawer for carpets, walls and gardens <span class=\"badge\">worth testing now</span></h3>\n<p>The judgement is a picture-matching job against thousands of real examples, not a rule you can look up, and a free model has no examples to match against</p>\n<p><strong>What it&#x27;s built on:</strong> Twelve years of check-in and check-out photos of the same items, so we know what four years of normal use looks like versus real damage, using an AI that looks at a photo of a carpet, wall or garden, is told the tenancy length and who lived there, and says where it sits between normal ageing and chargeable damage.</p>\n<p><strong>What we found:</strong> I checked whether this judgement is already available free and whether rivals do photo work. The deposit schemes and the landlord bodies publish expected item lifespans and the general principles for nothing, and at least one inventory app already sells photo analysis, so those parts are not yours alone. What I could not find anywhere public is a graded judgement built from matched before-and-after photos of the same item, which is the part that rests on your archive.</p>\n<p><strong>How it scored:</strong> (each out of 5) hard to copy 4, people will pay 3, easy to build 2, reusable elsewhere 2, built to last 3 (14 out of 25 overall).</p>\n<p><strong>Risk to you:</strong> 3/5 (moderate \u2014 show your sources; insurance for handling personal data is recommended)</p>\n<p><strong>A cheap first test:</strong> Offer a handful of agents a free trial where you manually grade five photos each against your archive and ask if they would pay monthly for this as a standing service.</p>\n<h4>Check it yourself</h4>\n<ul class=\"sources\">\n<li><a href=\"https://www.nrla.org.uk/news/how-long-should-your-rented-property-items-last-a-look-at-product-lifespans\" rel=\"nofollow noopener\" target=\"_blank\">How long should your rented property items last? A look at product lifespans</a></li>\n<li><a href=\"https://www.propertymark.co.uk/professional-standards/consumer-guides/landlords/fair-wear-and-tear.html\" rel=\"nofollow noopener\" target=\"_blank\">Fair wear and tear / Betterment and Apportionment</a></li>\n<li><a href=\"https://thepropertyai.co.uk/\" rel=\"nofollow noopener\" target=\"_blank\">AI Property Inventory Software for UK Letting Agents &amp; Inventory Clerks</a></li>\n</ul>\n<h2>Didn&#x27;t make the cut</h2>\n<p>We came up with these too, but set them aside \u2014 either because they&#x27;d be too easy for someone else to copy, or because not enough people would pay for them.</p>\n<h3>Inspector report grader that catches sloppy work same day</h3>\n<p>It scores against our own record of which report habits later lost disputes, and it plugs into the reports as they arrive</p>\n<p>We set it aside because not enough people would pay for it (people-will-pay 2/5).</p>\n<h3>Search the archive in plain English</h3>\n<p>The archive is private; no outside model can search it</p>\n<p>We set it aside because not enough people would pay for it (people-will-pay 2/5).</p>\n<h3>Check-in quality gate before the tenant gets the keys</h3>\n<p>It judges against our own evidence of what later fails, and it acts inside our workflow while there is still time to fix it</p>\n<p>We set it aside because not enough people would pay for it (people-will-pay 2/5).</p>\n<p>If you&#x27;d like us to help turn any of these ideas into a working tool \u2014 or you have any questions about this report \u2014 just email us at idea-uk@leopardess.uk.</p>\n<p>idea.uk finds and tests AI product ideas for your business, so you can spend your time building the ones most likely to pay off.</p>\n<hr>\n<p class=\"note\">Your report would be about <em>your</em> idea, researched the same way, with its own sources you can check. It costs \u00a329, a person reads it before it is sent, and if it turns up nothing worth acting on you get your money back.</p>"}$p432$::jsonb,
    updated_at = now()
FROM pages p
WHERE p.id = pc.page_id AND p.site_id='1244516d-014d-421c-88c6-090bb1e9552a'
  AND p.name='report-example' AND pc.position=2;

-- Refuse to dispatch if the update missed, or if ANY required LLM field is
-- missing on ANY section — the render would silently escalate to the LLM
-- writer, which on this page would falsify "nothing has been reworded".
DO $g$
DECLARE n int; missing text;
BEGIN
  SELECT count(*) INTO n FROM page_components pc
  JOIN pages p ON p.id = pc.page_id
  WHERE p.site_id='1244516d-014d-421c-88c6-090bb1e9552a' AND p.name='report-example'
    AND pc.position=2 AND pc.content_data->>'heading' = 'The report, in full';
  IF n <> 1 THEN
    RAISE EXCEPTION 'ABORT: expected exactly 1 refreshed section, found %', n;
  END IF;
  SELECT string_agg(cc.function || '.' || f.key, ', ') INTO missing
  FROM page_components pc
  JOIN pages p ON p.id = pc.page_id
  JOIN content_components cc ON cc.id = pc.component_id
  CROSS JOIN LATERAL jsonb_each(cc.input_schema->'fields') AS f(key,val)
  WHERE p.site_id='1244516d-014d-421c-88c6-090bb1e9552a' AND p.name='report-example'
    AND (f.val->>'required')::boolean IS TRUE
    AND NOT (pc.content_data ? f.key);
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION 'ABORT: required field(s) missing: % — the render would escalate to the LLM writer', missing;
  END IF;
END $g$;

INSERT INTO site_work_items
  (site_id, source, item_type, severity, summary, spec, priority, handler_agent, status, created_by, item_key)
SELECT p.site_id, 'manual-p4_32', 'page_rerender', 'medium',
  'Rebuild /report/example/index.html with the 28 July report and reworded provenance',
  jsonb_build_object('domain','idea.uk','page_id',p.id::text,
                     'filename','report/example/index.html',
                     'page_name',p.name,'reason','section_data_resolved'),
  85, 'page-rerender', 'triaged', 'idea.uk vm 9 session, p4_32',
  'page_rerender_report_example_p4_32_' || p.site_id::text
FROM pages p WHERE p.site_id='1244516d-014d-421c-88c6-090bb1e9552a' AND p.name='report-example';

COMMIT;

SELECT pc.position, pc.content_data->>'heading' AS heading,
       length(pc.content_data->>'content') AS content_len
FROM page_components pc JOIN pages p ON p.id=pc.page_id
WHERE p.site_id='1244516d-014d-421c-88c6-090bb1e9552a' AND p.name='report-example'
ORDER BY pc.position;
SELECT id, status, spec->>'reason' AS reason FROM site_work_items WHERE created_by LIKE '%p4_32%';
